choice:
choice Optional<ItemType> {
	Value { item: ItemType },
	Empty,
}

entries.signature:
map<infer Other>(
	_ transform: (_: ItemType) -> Other,
) -> Optional<Other>

andThen<infer Other>(
	_ step: (_: ItemType) -> Optional<Other>,
) -> Optional<Other>

pair<infer Other>(
	with other: Optional<Other>,
) -> Optional<{ first: ItemType, second: Other }>

toResult<infer FailureType>(
	failingWith reason: FailureType,
) -> Result<ItemType, FailureType>
